entries[27145] = { ["name"] = "Greater Blessing of Light", ["text"] = "360 Mana 40 yd range\nInstant\nReagents:\nSymbol of Kings\nGives all members of the raid or group that share the same class with the target the Greater Blessing of Light, increasing the effects of Holy Light spells used on the target by up to 580 and the effects of Flash of Light spells used on the target by up to 185. Lasts 30 min. Players may only have one Blessing on them per Paladin at any one time." }
entries[27146] = { ["name"] = "Left Piece of Lord Valthalak's Amulet", ["text"] = "2 sec cast\nReagents:\nTop Piece of Lord Valthalak's Amulet , Right Piece of Lord Valthalak's Amulet\nRecombines the left, right and top pieces of Lord Valthalak's Amulet into one whole." }
entries[27147] = { ["name"] = "Blessing of Sacrifice", ["text"] = "115 Mana 30 yd range\nInstant 30 sec cooldown\nPlaces a Blessing on the party member, transfering 81 damage taken per hit to the caster. Lasts 30 sec. Players may only have one Blessing on them per Paladin at any one time." }
