entries[27155] = { ["name"] = "Seal of Righteousness", ["text"] = "260 Mana\nInstant\nFills the Paladin with holy spirit for 30 sec, granting each melee attack an additional [1.2 * ( 2324 * 1.2 * 1.03 * Mainhand weapon max base speed / 100) + 0.03 * (Mainhand weapon max damage + Mainhand weapon min damage) / 2 + 1] Holy damage. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will cause 225 to 246 Holy damage to an enemy." }
