entries[27158] = { ["name"] = "Seal of the Crusader", ["text"] = "210 Mana\nInstant\nFills the Paladin with the spirit of a crusader for 30 sec, granting 495 melee attack power. The Paladin also attacks 40% faster, but deals less damage with each attack. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 20 sec, increasing Holy damage taken by up to 219. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
